import {floorOf,createDisplayBody,prepareDisplayBody,commitDisplayBodies} from './floor-display-coordinator.js';
import {worldDisplayText} from '../../domain/world-dynamics/display-text.js';
import {placeFloorBackgroundDisplay} from './floor-background-display-order.js';
import {worldDateText} from '../../domain/world-dynamics/prompts.js';
const categories=[['world','世界'],['region','地区'],['weather','天气'],['activity','活动'],['character','人物'],['opinion','舆论'],['plot','支线'],['aftermath','影响']];
const bodyNames={world:'动向内容',region:'动态内容',activity:'活动内容',opinion:'舆论内容',character:'动态',plot:'关键节点',aftermath:'影响'};
const prefixFields=text=>Object.fromEntries([...text.matchAll(/^([^：\n]+)：[ \t]*(.*)$/gm)].map(m=>[m[1].trim(),m[2].trim()]));
export function briefingItems(entries){return entries.flatMap(entry=>{
 if(entry.kind==='weather'){const location=entry.text.split('\n').find(line=>line.trim().startsWith('地点：'))?.trim().slice(3)??'';return entry.text.split('\n').filter(line=>line.trim()&&!line.trim().startsWith('地点：')).map((line,index)=>{const split=line.indexOf('：');return {id:entry.id+':'+index,kind:'weather',title:split<0?'天气环境':line.slice(0,split),date:'',location,body:split<0?line:line.slice(split+1).trimStart()};});}
 const label=bodyNames[entry.kind],marker=new RegExp('^'+label+'：[ \t]*','m'),found=marker.exec(entry.text),prefix=found?entry.text.slice(0,found.index):entry.text,f=prefixFields(prefix);let body=found?entry.text.slice(found.index+found[0].length):entry.text;
 if(entry.kind==='aftermath'){const matches=[...body.matchAll(/^有效至：[ \t]*(.*)$/gm)],last=matches.at(-1);if(last){f.有效至=last[1].trim();const before=body.slice(0,last.index),after=body.slice(last.index+last[0].length);body=after?before+after.replace(/^\n/,''):before.replace(/\n$/,'');}}
 const extra=prefix.split('\n').filter(line=>line.trim()&&!/^(名称|姓名|事件|时间|地点|完结日期)：/.test(line.trim())).join('\n');if(extra)body=extra+'\n'+body;
 return [{id:entry.id,kind:entry.kind,title:f.名称??f.姓名??f.事件??'世界动态',date:f.时间??[f.完结日期?`完结于 ${f.完结日期}`:'',f.有效至?`有效至 ${f.有效至}`:''].filter(Boolean).join(' · '),location:f.地点??'',body}];
});}
const fallback=':host{display:block}.ui-briefing [hidden]{display:none!important}.ui-briefing-body{white-space:pre-wrap;overflow-wrap:anywhere}.ui-briefing-tabs{display:flex;flex-wrap:wrap}';
export function mountWorldDynamicsDisplay({document:doc=globalThis.document,runtime,coordinator,styles}={}){
 let disposed=false,owned=null,reading=null;const release=()=>{if(owned?.details)reading={target:owned.target,selected:owned.selected,pages:new Map(owned.pages),open:owned.details.open};if(owned?.entry?.frontend)coordinator.requestCleanup({...owned,ownsChat:owned.formatSnapshot?.ownsChat});owned?.box.remove();owned=null;};
 function create(message,target){const box=doc.createElement('lantai-world-briefing');box.className='lantai-world-briefing';const shadow=box.attachShadow({mode:'open'}),style=doc.createElement('style');style.textContent=fallback;const details=doc.createElement('details');details.className='ui-briefing';details.open=true;const summary=doc.createElement('summary'),title=doc.createElement('span'),date=doc.createElement('time');title.textContent='世界简报';date.className='ui-briefing-date';summary.append(title,date);const tabs=doc.createElement('div');tabs.className='ui-briefing-tabs';tabs.setAttribute('role','tablist');tabs.setAttribute('aria-label','世界简报分类');const article=doc.createElement('article');article.className='ui-briefing-article';article.setAttribute('role','tabpanel');article.id='briefing-panel';const heading=doc.createElement('h3');heading.className='ui-briefing-title';const meta=doc.createElement('p');meta.className='ui-briefing-meta';const body=doc.createElement('p');body.className='ui-briefing-body';article.append(heading,meta,body);const pager=doc.createElement('div');pager.className='ui-briefing-pager';const prev=doc.createElement('button'),next=doc.createElement('button'),count=doc.createElement('span');for(const button of [prev,next]){button.type='button';button.className='ui-button ui-button--tertiary';}prev.textContent='上一条';next.textContent='下一条';count.className='ui-briefing-count';pager.append(prev,count,next);details.append(summary,tabs,article,pager);shadow.append(style,details);const state={mode:'builtin',box,shadow,style,details,date,tabs,heading,meta,body,prev,next,count,pager,message,target,selected:null,pages:new Map(),items:[],snapshot:null};if(reading?.target===target){state.selected=reading.selected;state.pages=new Map(reading.pages);details.open=reading.open;}
 const paint=()=>{const group=state.items.filter(item=>item.kind===state.selected),index=Math.min(state.pages.get(state.selected)??0,Math.max(0,group.length-1)),item=group[index];state.pages.set(state.selected,index);for(const button of [...tabs.children]){const selected=button.dataset.kind===state.selected;button.setAttribute('aria-selected',String(selected));if(selected)article.setAttribute('aria-labelledby',button.id);button.tabIndex=selected?0:-1;}heading.textContent=item?.title??'';meta.textContent=[item?.date,item?.location].filter(Boolean).join('\n');meta.hidden=!meta.textContent;body.textContent=item?.body??'';pager.hidden=group.length<=1;prev.disabled=index<=0;next.disabled=index>=group.length-1;count.textContent=group.length?`${index+1} / ${group.length}`:'';};
 const choose=kind=>{if(!runtime.isCurrent(state.snapshot))return;state.selected=kind;paint();};tabs.addEventListener('click',event=>{const button=event.target.closest?.('[data-kind]');if(button)choose(button.dataset.kind);});tabs.addEventListener('keydown',event=>{const buttons=[...tabs.children],index=buttons.indexOf(event.target);if(index<0||!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;event.preventDefault();const n=event.key==='Home'?0:event.key==='End'?buttons.length-1:(index+(event.key==='ArrowRight'?1:-1)+buttons.length)%buttons.length;choose(buttons[n].dataset.kind);buttons[n].focus();});for(const [button,step]of [[prev,-1],[next,1]])button.addEventListener('click',()=>{if(!button.disabled&&runtime.isCurrent(state.snapshot)){state.pages.set(state.selected,(state.pages.get(state.selected)??0)+step);paint();}});state.paint=paint;return state;}
 function createRegex(message,target,raw){const box=doc.createElement('div');box.className='lantai-world-briefing';box.setAttribute('data-world-display','regex');const style=doc.createElement('style');style.textContent='.lantai-world-briefing-body{white-space:pre-wrap;overflow-wrap:anywhere}.lantai-world-briefing-formatted{white-space:normal}';const entry=createDisplayBody(doc,'lantai-world-briefing-body',raw);box.append(style,entry.body);return {mode:'regex',box,entry,message,target,formatSnapshot:null};}
 const collect=({messages,target})=>{const info=runtime.inspect();if(disposed||info.status!=='ready'||!runtime.isCurrent(info)||JSON.stringify(info.target)!==target){release();return [];}const message=messages.find(node=>floorOf(node)===info.reply.floor);if(!message){release();return [];}const mode=info.mode??'builtin',raw=mode==='regex'?worldDisplayText(info):'';if(!owned||owned.message!==message||owned.target!==target||owned.mode!==mode){release();owned=mode==='regex'?createRegex(message,target,raw):create(message,target);}const state=owned;state.snapshot=info;const parent=message.querySelector('.mes_block')??message;placeFloorBackgroundDisplay(parent,state.box);if(mode==='regex'){state.floor=info.reply.floor;return [{id:'world-briefing:'+state.entry.scope,message,floor:info.reply.floor,target,content:raw,busy:false,bind:snapshot=>{state.formatSnapshot=snapshot;},current:()=>owned===state&&runtime.isCurrent(info)&&message.isConnected!==false,prepare:snapshot=>prepareDisplayBody(state.entry,raw,snapshot),commit(update,snapshot){if(owned!==state||!runtime.isCurrent(info))return {refresh:false,checks:[]};state.formatSnapshot=snapshot;return commitDisplayBodies([update],snapshot,doc);}}];}return [{id:'world-briefing',message,floor:info.reply.floor,target,content:JSON.stringify([info.entries,info.date,info.theme,info.ticket]),busy:false,current:()=>owned===state&&runtime.isCurrent(info)&&message.isConnected!==false,prepare:async()=>{let css=null;try{css=await styles(info.theme);}catch{}return {css,info};},commit({css,info}){if(owned!==state||!runtime.isCurrent(info))return {refresh:false,checks:[]};state.snapshot=info;state.box.setAttribute('data-ui-theme',info.theme);state.style.textContent=fallback+'\n'+(css??'');state.date.textContent=worldDateText(info.date);state.items=briefingItems(info.entries);const available=categories.filter(([kind])=>state.items.some(item=>item.kind===kind)),keys=available.map(([kind])=>kind);if(!keys.includes(state.selected))state.selected=keys[0];state.tabs.setAttribute('data-count',String(keys.length));const old=[...state.tabs.children].map(button=>button.dataset.kind);if(JSON.stringify(old)!==JSON.stringify(keys)){state.tabs.replaceChildren(...available.map(([kind,label])=>{const button=doc.createElement('button');button.type='button';button.className='ui-button ui-button--tertiary';button.dataset.kind=kind;button.setAttribute('role','tab');button.id='briefing-tab-'+kind;button.setAttribute('aria-controls','briefing-panel');button.textContent=label;return button;}));}state.paint();return {refresh:false,checks:[]};}}];};
 const off=coordinator.register(collect),changed=runtime.subscribe(()=>coordinator.requestRefresh());return {dispose(){disposed=true;changed();off();release();}};
}
